package jp.noppy.lumamusic.core.dsp

import org.junit.Assert.*
import org.junit.Test
import kotlin.math.*

class PcmDspTest {
    private fun sine(rate:Int,frequency:Double,frames:Int=rate, amplitude:Double=.1)=FloatArray(frames*2){(amplitude*sin(2*PI*frequency*(it/2)/rate)).toFloat()}
    private fun rms(a:FloatArray,start:Int=a.size/2)=sqrt(a.drop(start).sumOf{it.toDouble()*it}/(a.size-start))
    @Test fun directPreservesEveryFloatIncludingSpecialValues() { val a=floatArrayOf(-1f,0f,Float.NaN,Float.POSITIVE_INFINITY,.999f); val e=PcmDspEngine(44100,1); e.configure(DspConfig(bands=List(10){12f},autoEnabled=true,widthEnabled=true)); assertArrayEquals(a.map{it.toRawBits()}.toIntArray(),e.process(a).map{it.toRawBits()}.toIntArray()) }
    @Test fun flatEnhancePreservesSignalAndChannels() { for(rate in listOf(44100,48000)){ val e=PcmDspEngine(rate,2);e.configure(DspConfig(mode=SoundMode.ENHANCE)); val a=sine(rate,1000.0);assertArrayEquals(a,e.process(a),1e-6f) } }
    @Test fun equalizerMeasuredResponseMatchesPlusAndMinusThreeDb() { for(rate in listOf(44100,48000))for(gain in listOf(-3f,3f)){val e=PcmDspEngine(rate,2);e.configure(DspConfig(mode=SoundMode.ENHANCE,bands=List(10){if(it==5)gain else 0f})); assertEquals(gain.toDouble(),e.responseDb(1000.0),.05); val a=e.process(sine(rate,1000.0));val expected=10.0.pow((gain-max(gain,0f)-if(gain>0)1 else 0)/20.0);assertEquals(expected,rms(a)/sqrt(.005),.03) } }
    @Test fun extremeSettingsAndInvalidSamplesAreBounded() { val e=PcmDspEngine(48000,2);e.configure(DspConfig(mode=SoundMode.ENHANCE,bands=List(10){12f},preampDb=6f,widthEnabled=true,width=1.2f));val a=e.process(FloatArray(4096){if(it%3==0)Float.NaN else 1f});assertTrue(a.all{it.isFinite()&&abs(it)<=1f}) }
    @Test fun widthZeroMakesStereoMonoAndMonoIsSafe() { val e=PcmDspEngine(48000,2);e.configure(DspConfig(mode=SoundMode.ENHANCE,widthEnabled=true,width=0f));val a=e.process(FloatArray(200){if(it%2==0).5f else -.25f});for(i in a.indices step 2)assertEquals(a[i],a[i+1],1e-6f);val mono=PcmDspEngine(44100,1);mono.configure(DspConfig(mode=SoundMode.ENHANCE,widthEnabled=true,width=1.2f));assertTrue(mono.process(FloatArray(100){.2f}).all{it.isFinite()}) }
    @Test fun processingDoesNotDependOnBufferSplits() { val cfg=DspConfig(mode=SoundMode.ENHANCE,bands=List(10){if(it==3)-3f else 0f});val a=sine(44100,250.0,2000);val x=PcmDspEngine(44100,2);val y=PcmDspEngine(44100,2);x.configure(cfg);y.configure(cfg);val expected=x.process(a);val split=y.process(a.copyOfRange(0,666))+y.process(a.copyOfRange(666,a.size));assertArrayEquals(expected,split,1e-6f) }
    @Test fun normalizeUsesMeasuredLoudnessAndCapsPositiveGain() { assertEquals(0.0,normalizationGainDb(null,-16.0),0.0);assertEquals(6.0,normalizationGainDb(-40.0,-16.0),0.0);assertEquals(-6.0,normalizationGainDb(-10.0,-16.0),0.0) }
    @Test fun allBandsHaveRealResponseAndLowRateSkipsNyquistBand(){for(rate in listOf(44100,48000))for(i in 0..9)for(g in listOf(-3f,3f)){val e=PcmDspEngine(rate,2);e.configure(DspConfig(mode=SoundMode.ENHANCE,bands=List(10){if(it==i)g else 0f}));assertEquals(g.toDouble(),e.responseDb(EQ_FREQUENCIES[i]),.05)};val low=PcmDspEngine(22050,2);low.configure(DspConfig(mode=SoundMode.ENHANCE,bands=List(10){if(it==9)12f else 0f}));assertEquals(0.0,low.responseDb(5000.0),1e-7);assertEquals(0.0,low.gainDb,1e-7)}
    @Test fun leftFilterNeverLeaksIntoSilentRight(){val e=PcmDspEngine(48000,2);e.configure(DspConfig(mode=SoundMode.ENHANCE,bands=List(10){if(it==5)-3f else 0f}));val a=sine(48000,1000.0);for(i in 1 until a.size step 2)a[i]=0f;val out=e.process(a);assertTrue(out.indices.filter{it%2==1}.all{out[it]==0f})}
    @Test fun modeChangesRampAndDirectThenPreservesBits(){val e=PcmDspEngine(48000,2);e.configure(DspConfig(mode=SoundMode.ENHANCE,bands=List(10){-3f}));e.process(sine(48000,997.0,2000));e.configure(DspConfig());assertFalse(e.isDirect);e.process(sine(48000,997.0,2000));assertTrue(e.isDirect);val a=sine(48000,997.0,100);assertArrayEquals(a,e.process(a),0f)}
    @Test fun autoCannotOverwriteManualBand(){val a=TrackAnalysis(-16.0,.5,List(10){-2f},48000,48000,true);val e=PcmDspEngine(48000,2);e.configure(DspConfig(mode=SoundMode.ENHANCE,autoEnabled=true,bands=List(10){if(it==5)3f else 0f}),a);val manual=PcmDspEngine(48000,2);manual.configure(DspConfig(mode=SoundMode.ENHANCE,bands=List(10){if(it==5)3f else -2f}));assertEquals(manual.responseDb(1000.0),e.responseDb(1000.0),1e-6)}
    @Test fun disabledAnalysisDoesNotChangeFlatSignal(){val a=TrackAnalysis(-3.0,1.0,List(10){-2f},48000,48000,true);val e=PcmDspEngine(48000,2);e.configure(DspConfig(mode=SoundMode.ENHANCE),a);assertEquals(0.0,e.gainDb,1e-7);val x=sine(48000,997.0);assertArrayEquals(x,e.process(x),1e-6f)}
}
